<script setup lang="ts">
import {ref,computed} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api,login,session,isDemo} from '../api';import Icon from '../components/Icon.vue'
const route=useRoute(),router=useRouter();const mode=computed(()=>route.path.slice(1));const email=ref(''),password=ref(''),name=ref(''),phone=ref(''),error=ref(''),message=ref(''),busy=ref(false)
const title=computed(()=>({login:'Qué bueno tenerte de vuelta.',register:'Tu vehículo, en buenas manos.',forgot:'Recupera tu acceso.',reset:'Una nueva contraseña.'}[mode.value]))
async function submit(){busy.value=true;error.value='';try{if(mode.value==='login'){await login(email.value,password.value);router.push('/')}
else if(mode.value==='register'){await api('/auth/register','POST',{email:email.value,password:password.value,name:name.value,phone:phone.value});await login(email.value,password.value);router.push('/')}
else if(mode.value==='forgot'){const r=await api('/auth/forgot','POST',{email:email.value});message.value=r.message}
else {await api('/auth/reset','POST',{token:route.query.token,password:password.value});session.user=null;message.value='Contraseña actualizada. Ya puedes iniciar sesión.'}}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="auth-layout"><section class="auth-story"><div class="brand"><span class="brand-icon"><Icon name="wrench" :size="26"/></span><span>Taller<span class="brand-light">Meco</span></span></div><div class="auth-headline"><span class="capsule"><span class="status-dot"></span>EL TALLER, CONECTADO</span><h1>Menos pendientes.<br>Más kilómetros<br><em>por recorrer.</em></h1><p>Personas, vehículos y servicios.<br>Todo conectado para trabajar mejor.</p><div class="auth-illustration" aria-hidden="true"><div class="orbit"></div><div class="car-card"><Icon name="car" :size="90"/><div><span>Todo bajo control</span><strong>Listo para el camino</strong></div><span class="round-check"><Icon name="check"/></span></div><div class="mini-card"><Icon name="shield"/><span>Cada servicio, con historial.</span></div></div></div><small>Un buen servicio empieza con una buena organización.</small></section><section class="auth-form-area"><div class="auth-form"><p class="eyebrow">BIENVENIDO A TALLERMECO</p><h2>{{title}}</h2><p class="muted">{{mode==='login'?'Inicia sesión para entrar a tu espacio de trabajo.':mode==='register'?'Crea tu cuenta para consultar vehículos y servicios.':mode==='forgot'?'Te enviaremos un enlace válido por 30 minutos.':'Usa al menos 12 caracteres para proteger tu cuenta.'}}</p><div v-if="message" class="success-panel" role="status"><Icon name="check"/>{{message}}<RouterLink to="/login">Volver al inicio de sesión</RouterLink></div><div v-if="isDemo" class="demo-access"><strong>Explora el prototipo</strong><p>Datos ficticios · Sin contraseña · Solo en este navegador</p><div class="demo-buttons"><button v-for="r in ['admin','mecanico','cliente']" class="btn secondary" @click="email=r+'@tallermeco.local';submit()">{{r==='admin'?'Administración':r==='mecanico'?'Mecánico':'Cliente'}}</button></div></div><form v-if="!message&&!isDemo" @submit.prevent="submit"><label v-if="mode==='register'">Nombre completo<input v-model="name" required maxlength="160" autocomplete="name" placeholder="Tu nombre y apellido"></label><label v-if="mode!=='reset'">Correo electrónico<input v-model="email" type="email" required autocomplete="username" maxlength="254" placeholder="nombre@correo.com"></label><label v-if="mode==='register'">Teléfono <small>(opcional)</small><input v-model="phone" maxlength="30" autocomplete="tel" placeholder="55 1234 5678"></label><label v-if="mode!=='forgot'">Contraseña<input v-model="password" type="password" required :minlength="mode==='login'?1:12" maxlength="128" :autocomplete="mode==='login'?'current-password':'new-password'" placeholder="Tu contraseña"><small v-if="mode!=='login'">Mínimo 12 caracteres. Puedes usar una frase.</small></label><RouterLink v-if="mode==='login'" class="forgot-link" to="/forgot">¿Olvidaste tu contraseña?</RouterLink><p v-if="error" class="error" role="alert">{{error}}</p><button class="btn primary full" :disabled="busy">{{busy?'Un momento…':mode==='login'?'Entrar a mi taller':mode==='register'?'Crear mi cuenta':mode==='forgot'?'Enviar enlace':'Guardar contraseña'}}<Icon name="arrow"/></button></form><p class="auth-switch" v-if="mode==='login'&&!isDemo">¿Eres cliente y aún no tienes cuenta? <RouterLink to="/register">Regístrate</RouterLink></p><p class="auth-switch" v-else-if="!isDemo"><RouterLink to="/login">Volver al inicio de sesión</RouterLink></p><div class="auth-secure"><Icon name="shield" :size="16"/>{{isDemo?'Vista de demostración · No uses información real':'Acceso personal · Tu información protegida'}}</div></div></section></div></template>
